import networkx as nx
def faces(G):
  ok,emb=nx.check_planarity(G)
  assert ok
  seen=set(); F=0
  for u,v in emb.edges():
    if (u,v) not in seen:
      emb.traverse_face(u,v,mark_half_edges=seen); F+=1
  return F
Gs={'tri':nx.cycle_graph(3),'K4':nx.complete_graph(4),'cube':nx.hypercube_graph(3),'grid':nx.grid_2d_graph(4,5),'wheel':nx.wheel_graph(9),'ico':nx.icosahedral_graph(),'dod':nx.dodecahedral_graph()}
res={k:(G.number_of_nodes(),G.number_of_edges(),faces(G)) for k,G in Gs.items()}
assert res['tri']==(3,3,2) and res['K4']==(4,6,4) and res['cube']==(8,12,6)
assert res['ico']==(12,30,20) and res['dod']==(20,30,12)
for V,E,F in res.values(): assert V-E+F==2
P=nx.path_graph(5); assert (5,4)==(P.number_of_nodes(),P.number_of_edges()) and faces(P)==1

